package fraymus.workspace;
import org.json.*;
import java.nio.file.*;
import java.util.*;
/** Seen-source development regression. Never a new held physical trial. */
public final class TabletopTrackerReplay {
 public static void main(String[] args)throws Exception{var exported=new JSONObject(Files.readString(Path.of(args[0])));var run=exported.getJSONObject("run");var images=exported.getJSONArray("images");var first=WorldObservationStore.decode(Base64.getDecoder().decode(images.getJSONObject(0).getString("image")));var tracker=new RigidTargetTracker(first,PixelTracker.Box.from(run.getJSONArray("box")));var plane=new PlaneCalibration(run.getJSONObject("geometry").getJSONObject("definition"));var guard=new MatReferenceGuard(WorldObservationStore.decode(Base64.getDecoder().decode(exported.getString("checkImage"))),plane.definition());var box=PixelTracker.Box.from(run.getJSONArray("box"));var filter=new TabletopFilter(run.getJSONObject("seed").getDouble("seconds"),plane.project(box.x()+box.w()/2,box.y()+box.h()/2));var rows=new JSONArray();int accepted=0,metricAccepted=0;for(int i=1;i<images.length();i++){var image=WorldObservationStore.decode(Base64.getDecoder().decode(images.getJSONObject(i).getString("image")));var row=tracker.update(image);var reference=guard.check(image);double[] measurement=null;if(row.getBoolean("accepted")){var point=PlaneCalibration.point(row.getJSONArray("point"));if(plane.inPlane(point[0],point[1]))measurement=plane.project(point[0],point[1]);}var estimate=filter.step(images.getJSONObject(i).getJSONObject("reference").getDouble("seconds"),measurement,row.getBoolean("accepted")&&reference.getBoolean("valid"),plane.definition().getDouble("anchorSigmaM"));if(estimate.getBoolean("accepted"))metricAccepted++;row.put("estimate",estimate).put("reference",reference);if(row.getBoolean("accepted"))accepted++;rows.put(row.put("ordinal",i));}var out=new JSONObject().put("version",RigidTargetTracker.VERSION).put("codeSha256",TabletopStore.identity()).put("runId",run.getString("id")).put("frames",rows.length()).put("accepted",accepted).put("metricAccepted",metricAccepted).put("rows",rows).put("scope","Seen physical slide reused only as development regression. Full appearance/reference/filter development replay using original image bytes, geometry and times; not new footage or independent physical validation.");Files.writeString(Path.of(args[1]),out.toString(2));System.out.println(new JSONObject().put("frames",rows.length()).put("accepted",accepted).put("metricAccepted",metricAccepted).put("last",rows.getJSONObject(rows.length()-1)));}
}
